import uuid

import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.ShowStoreOffer{OfferID: uuid.MustParse("0575c61f-a5da-4b7f-9961-ffda2908861e"), Type:
# packet.StoreOfferTypeServerPage}
SERVER_PAGE = bytes.fromhex("7f4bdaa51fc675051e860829daff619902")

# generated by gophertunnel b8bd735:
# packet.ShowStoreOffer{OfferID: uuid.MustParse("ffffffff-ffff-ffff-0000-000000000001"), Type:
# packet.StoreOfferTypeMarketplace}
WIDE = bytes.fromhex("ffffffffffffffff010000000000000000")

GOLDENS = [
    pytest.param(
        v2225.ShowStoreOfferPacket(
            offer_id=uuid.UUID("0575c61f-a5da-4b7f-9961-ffda2908861e"),
            redirect_type=v2225.ShowStoreOfferRedirectType.THIRD_PARTY_SERVER_PAGE,
        ),
        SERVER_PAGE,
        id="server-page",
    ),
    pytest.param(
        v2225.ShowStoreOfferPacket(
            offer_id=uuid.UUID("ffffffff-ffff-ffff-0000-000000000001"),
            redirect_type=v2225.ShowStoreOfferRedirectType.MARKETPLACE_OFFER,
        ),
        WIDE,
        id="wide-offer-id",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_show_store_offer_is_packet_91(version):
    assert version.PACKETS[91] is version.ShowStoreOfferPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_show_store_offer_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_show_store_offer_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
